package initdb

import (
	"sync"

	"github.com/goopg/goopg/internal/executor"
)

// pgAttributeMeta is the pg_attribute metadata a PostgreSQL 18.3 initdb leaves
// on a system-relation column (pgAttributeInitdbMeta, generated by
// scripts/gen-pg-attribute-meta.py). M0149-0001g slice 17.
type pgAttributeMeta struct {
	TypeOID   uint32
	Collation uint32
	Align     byte
	ByVal     bool
	NDims     int
	Storage   byte
	NotNull   bool
	TypMod    int
	ACL       string // aclitemout text with "B" = bootstrap superuser; "" = NULL
}

var pgBootstrapRelNameByOID = sync.OnceValue(func() map[uint32]string {
	m := map[uint32]string{}
	for _, r := range pgClassBootstrapRels() {
		m[r.OID] = r.RelName
	}
	return m
})

// pgAttributeInitdbMetaFor returns PG's metadata for column attName of the
// bootstrap relation relOID, when PG has that column with the same atttypid
// goopg writes. A differing type (index columns keyed on cstring by name_ops)
// is a storage-format difference, not metadata, and is left to goopg.
func pgAttributeInitdbMetaFor(relOID uint32, attName string, typeOID uint32) (pgAttributeMeta, bool) {
	rel, ok := pgBootstrapRelNameByOID()[relOID]
	if !ok {
		return pgAttributeMeta{}, false
	}
	m, ok := pgAttributeInitdbMeta[rel+"."+attName]
	if !ok || m.TypeOID != typeOID {
		return pgAttributeMeta{}, false
	}
	return m, true
}

// pgAttributeACLDatum encodes an initdb column ACL (attacl), or NULL.
func pgAttributeACLDatum(m pgAttributeMeta, what string) executor.Datum {
	if m.ACL == "" {
		return executor.NullDatum
	}
	return initdbACLDatum(m.ACL, what)
}
